  // src/shard-modules/shuffleTextModule.ts
  function shuffleString(str) {
    return str.split("").sort(() => Math.random() - Math.random()).join("");
  }
  var ShuffleTextModule = class extends ShardModule {
    effect(_context, target) {
      const id = setInterval(() => {
        try {
          target.textContent = shuffleString(target.textContent);
        } catch {
          clearInterval(id);
        }
      }, 1e3);
    }
  };

  // src/subscreens/dark-magic-subscreen/tome-of-knowledge-pages/base.ts
  var BasePage = class {
    load(_container) {
    }
  };
  var PageMarkup = class {
    static text({ content, fontSize = "md" }) {
      const p3 = document.createElement("p");
      p3.innerHTML = content;
      addDynamicClass(p3, {
        base: {
          color: "var(--tmd-text, black)",
          fontSize: fontSize === "sm" ? "0.5em" : fontSize === "md" ? "1.2em" : "1.8em",
          fontFamily: "Yusei Magic",
          margin: "0",
          marginTop: "0.25em"
        }
      });
      return p3;
    }
    static flexContainer({
      direction = "row",
      gapX = "0",
      gapY = "0",
      wrap = "nowrap"
    } = {}) {
      const container = document.createElement("div");
      addDynamicClass(container, {
        base: {
          display: "flex",
          flexDirection: direction,
          columnGap: gapX,
          rowGap: gapY,
          flexWrap: wrap
        }
      });
      return container;
    }
    static image({
      source,
      width,
      height
    }) {
      const img = document.createElement("img");
      img.src = source;
      img.style.width = width;
      img.style.height = height;
      return img;
    }
  };

